def solve(path, new_suffix):
    if "/" in path:
        parent, name = path.rsplit("/", 1)
        prefix = parent + "/"
    else:
        name = path
        prefix = ""
    if name.startswith(".") and name.count(".") == 1:
        stem = name
    elif "." in name:
        stem = name.rsplit(".", 1)[0]
    else:
        stem = name
    return prefix + stem + new_suffix
